import{c as t,S as o,j as s,m as i}from"./chunks/framework.Clfj75He.js";const p=JSON.parse('{"title":"Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"TimeseriesTools/extensions.md","filePath":"TimeseriesTools/extensions.md","lastUpdated":null}'),a={name:"TimeseriesTools/extensions.md"};function d(r,e,n,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="Extensions" tabindex="-1">Extensions <a class="header-anchor" href="#Extensions" aria-label="Permalink to &quot;Extensions {#Extensions}&quot;">​</a></h1><p><code>TimeseriesTools</code> exposes most of its analysis surface as package extensions. The function stubs live in core, but each method is only loaded when you <code>using</code> the corresponding package. This keeps the base load light and prevents the package from pulling unwanted heavy dependencies (<code>CUDA</code>, <code>Makie</code>, <code>DSP</code>, …) into every project.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">Loaded by</th><th style="text-align:right;">Provides</th></tr></thead><tbody><tr><td style="text-align:right;"><code>DSPExt</code></td><td style="text-align:right;"><code>using DSP</code></td><td style="text-align:right;"><a href="./@ref"><code>bandpass</code></a>, <a href="./@ref"><code>highpass</code></a>, <a href="./@ref"><code>lowpass</code></a>, <a href="./@ref"><code>hilbert</code></a>, <a href="./@ref"><code>analyticphase</code></a>, <a href="./@ref"><code>analyticamplitude</code></a>, <a href="./@ref"><code>instantaneousfreq</code></a>, <a href="./@ref"><code>phasestitch</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#downsample"><code>downsample</code></a></td></tr><tr><td style="text-align:right;"><code>DataInterpolationsExt</code></td><td style="text-align:right;"><code>using DataInterpolations</code></td><td style="text-align:right;"><a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.interpolate"><code>interpolate</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.upsample"><code>upsample</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.resample"><code>resample</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#impute"><code>impute</code></a> (1-D / per-axis)</td></tr><tr><td style="text-align:right;"><code>DataInterpolationsNDExt</code></td><td style="text-align:right;"><code>using DataInterpolationsND</code></td><td style="text-align:right;"><a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.interpolate"><code>interpolate</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.upsample"><code>upsample</code></a>, <a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/interpolation#TimeseriesTools.resample"><code>resample</code></a> (joint multi-axis)</td></tr><tr><td style="text-align:right;"><code>ContinuousWaveletsExt</code></td><td style="text-align:right;"><code>using ContinuousWavelets</code></td><td style="text-align:right;"><a href="./@ref"><code>waveletspectrogram</code></a></td></tr><tr><td style="text-align:right;"><code>CUDAExt</code></td><td style="text-align:right;"><code>using CUDA, ContinuousWavelets</code></td><td style="text-align:right;">GPU-accelerated wavelet transform</td></tr><tr><td style="text-align:right;"><code>AutocorrelationsExt</code></td><td style="text-align:right;"><code>using Autocorrelations</code></td><td style="text-align:right;"><code>fftacf</code>, <code>dotacf</code>, <a href="./@ref"><code>msdist</code></a></td></tr><tr><td style="text-align:right;"><code>ComplexityMeasuresExt</code></td><td style="text-align:right;"><code>using ComplexityMeasures</code></td><td style="text-align:right;">apply estimators directly to <code>AbstractTimeseries</code></td></tr><tr><td style="text-align:right;"><code>GeneralizedPhaseExt</code></td><td style="text-align:right;"><code>using GeneralizedPhase</code></td><td style="text-align:right;"><code>generalizedphase</code></td></tr><tr><td style="text-align:right;"><code>NaturalNeighboursExt</code></td><td style="text-align:right;"><code>using NaturalNeighbours</code></td><td style="text-align:right;">2-D scattered interpolation</td></tr><tr><td style="text-align:right;"><code>SignalDecompositionExt</code></td><td style="text-align:right;"><code>using SignalDecomposition</code></td><td style="text-align:right;">trend/oscillation decomposition</td></tr><tr><td style="text-align:right;"><code>OptimExt</code></td><td style="text-align:right;"><code>using Optim</code></td><td style="text-align:right;">MAPPLE refinement (<a href="/TimeseriesDocs.jl/dev/TimeseriesTools/analysis/peaks#StatsAPI.fit!-Union{Tuple{D}, Tuple{d}, Tuple{T}, Tuple{MAPPLE, AbstractDimVector{T, D}}} where {T, d, D&lt;:(Tuple{var&quot;#s1&quot;} where var&quot;#s1&quot;&lt;:d)}"><code>fit!</code></a>)</td></tr><tr><td style="text-align:right;"><code>BootstrapExt</code></td><td style="text-align:right;"><code>using Bootstrap</code></td><td style="text-align:right;"><a href="./@ref"><code>bootstrapmean</code></a>, <a href="./@ref"><code>bootstrapmedian</code></a>, <a href="./@ref"><code>bootstrapaverage</code></a></td></tr></tbody></table><h2 id="Why-extensions?" tabindex="-1">Why extensions? <a class="header-anchor" href="#Why-extensions?" aria-label="Permalink to &quot;Why extensions? {#Why-extensions?}&quot;">​</a></h2><ul><li><p><strong>Faster cold start</strong>: no precompile-time cost for capabilities you don&#39;t use.</p></li><li><p><strong>No version churn</strong>: heavy deps (CUDA, Makie, DSP) move quickly; a weak dep means TimeseriesTools doesn&#39;t force a particular version on the rest of your project.</p></li><li><p><strong>Discoverable failure mode</strong>: calling <code>bandpass(x)</code> without <code>using DSP</code> returns <code>x</code> unchanged (the stub) rather than throwing a <code>MethodError</code>. (See the warning at the top of each function&#39;s docstring.)</p></li></ul>',5)])])}const x=t(a,[["render",d]]);export{p as __pageData,x as default};
